export type RequestBody = PaymentTokenRequest;

/** Payment Token Request where the `source` defines the type of instrument to be stored. */
export interface PaymentTokenRequest {
  /**
   * Customer Request
   * This object defines a customer in your system. Use it to manage customer profiles, save payment methods and contact details.
   */
  customer?: {
    /** The unique ID for a customer in merchant's or partner's system of records. */
    id?: MerchantPartnerCustomerId;

    /** Merchants and partners may already have a data-store where their customer information is persisted. Use merchant_customer_id to associate the PayPal-generated customer.id to your representation of a customer. */
    merchant_customer_id?: string;
  };
  payment_source: PaymentSourceRequest;
}

/** The unique ID for a customer generated by PayPal. */
export type MerchantPartnerCustomerId = string;

/** The payment method to vault with the instrument details. */
export interface PaymentSourceRequest {
  /**
   * Card Request
   * A Resource representing a request to vault a Card.
   */
  card?: {
    /** The card holder's name as it appears on the card. */
    name?: string;

    /** The primary account number (PAN) for the payment card. */
    number?: string;

    /** The card expiration year and month, in [Internet date format](https://tools.ietf.org/html/rfc3339#section-5.6) For example: 2028-04 */
    expiry?: DateYearMonth;

    /** The three- or four-digit security code of the card. Also known as the CVV, CVC, CVN, CVE, or CID. This parameter cannot be present in the request when `payment_initiator=MERCHANT`. */
    security_code?: string;

    /** The card brand or network. Typically used in the response. */
    brand?: CardBrand;

    /**
     * Portable Postal Address (Medium-Grained)
     * The portable international postal address. Maps to [AddressValidationMetadata](https://github.com/googlei18n/libaddressinput/wiki/AddressValidationMetadata) and HTML 5.1 [Autofilling form controls: the autocomplete attribute](https://www.w3.org/TR/html51/sec-forms.html#autofilling-form-controls-the-autocomplete-attribute).
     */
    billing_address?: {
      /** The first line of the address, such as number and street, for example, `173 Drury Lane`. Needed for data entry, and Compliance and Risk checks. This field needs to pass the full address. */
      address_line_1?: string;

      /** The second line of the address, for example, a suite or apartment number. */
      address_line_2?: string;

      /** A city, town, or village. Smaller than `admin_area_level_1`. */
      admin_area_2?: string;

      /** The highest-level sub-division in a country, which is usually a province, state, or ISO-3166-2 subdivision. This data is formatted for postal delivery, for example, `CA` and not `California`. Value, by country, is:<ul><li>UK. A county.</li><li>US. A state.</li><li>Canada. A province.</li><li>Japan. A prefecture.</li><li>Switzerland. A *kanton*.</li></ul> */
      admin_area_1?: string;

      /** The postal code, which is the ZIP code or equivalent. Typically required for countries with a postal code or an equivalent. See [postal code](https://en.wikipedia.org/wiki/Postal_code). */
      postal_code?: string;
      country_code: CountryCode;
    };
    network_transaction_reference?: NetworkTransactionReferenceRequest;
  };
  token?: TokenRequest;
}

/** The year and month, in ISO-8601 `YYYY-MM` date format. See [Internet date and time format](https://tools.ietf.org/html/rfc3339#section-5.6). */
export type DateYearMonth = string;

/** The card network or brand. Applies to credit, debit, gift, and payment cards. */
export type CardBrand = ("VISA" | "MASTERCARD" | "DISCOVER" | "AMEX" | "SOLO" | "JCB" | "STAR" | "DELTA" | "SWITCH" | "MAESTRO" | "CB_NATIONALE" | "CONFIGOGA" | "CONFIDIS" | "ELECTRON" | "CETELEM" | "CHINA_UNION_PAY" | "DINERS" | "ELO" | "HIPER" | "HIPERCARD" | "RUPAY" | "GE" | "SYNCHRONY" | "EFTPOS" | "CARTE_BANCAIRE" | "STAR_ACCESS" | "PULSE" | "NYCE" | "ACCEL" | "UNKNOWN") & ("VISA" | "MASTERCARD" | "DISCOVER" | "AMEX" | "SOLO" | "JCB" | "STAR" | "DELTA" | "SWITCH" | "MAESTRO" | "CB_NATIONALE" | "CONFIGOGA" | "CONFIDIS" | "ELECTRON" | "CETELEM" | "CHINA_UNION_PAY" | "DINERS" | "ELO" | "HIPER" | "HIPERCARD" | "RUPAY" | "GE" | "SYNCHRONY" | "EFTPOS" | "CARTE_BANCAIRE" | "STAR_ACCESS" | "PULSE" | "NYCE" | "ACCEL" | "UNKNOWN");

/** The [2-character ISO 3166-1 code](/api/rest/reference/country-codes/) that identifies the country or region.<blockquote><strong>Note:</strong> The country code for Great Britain is <code>GB</code> and not <code>UK</code> as used in the top-level domain names for that country. Use the `C2` country code for China worldwide for comparable uncontrolled price (CUP) method, bank card, and cross-border transactions.</blockquote> */
export type CountryCode = string;

export type NetworkTransactionReferenceRequest = unknown;

/** The Tokenized Payment Source representing a Request to Vault a Token. */
export interface TokenRequest {
  /** The PayPal-generated ID for the token. */
  id: string;

  /** The tokenization method that generated the ID. */
  type: "SETUP_TOKEN" & "SETUP_TOKEN";
}
